"""Beginner-first, read-only P5 presentation."""
import html

def e(value): return html.escape(str(value))
def pct(value): return "样本不足" if value is None else f"{value*100:.1f}%"

CSS="""
*{box-sizing:border-box}body{margin:0;background:#07111b;color:#e8f0f5;font-family:"Microsoft YaHei",system-ui,sans-serif}.wrap{max-width:1380px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;gap:18px;align-items:flex-start}.brand{font-size:24px;font-weight:850}.brand em{font-style:normal;color:#45d0a4}.sub,.muted{color:#8295a5;font-size:13px}.lock{background:#3a2027;color:#ff9aaa;border:1px solid #68313d;border-radius:99px;padding:7px 12px;font-size:12px}.tabs{display:flex;gap:8px;margin:22px 0 14px}.tabs a{color:#a9bdca;text-decoration:none;padding:9px 14px;border-radius:9px;background:#0c1a25;border:1px solid #1b3140}.tabs a.active{color:#07111b;background:#7ddfc1;border-color:#7ddfc1;font-weight:750}.hero{padding:24px;border-radius:16px;background:linear-gradient(135deg,#102536,#0b1b27);border:1px solid #29485b;display:grid;grid-template-columns:1.5fr 1fr;gap:20px}.eyebrow{color:#7ddfc1;font-size:13px;font-weight:800}.hero h1{font-size:30px;margin:8px 0 10px}.action{background:#071722;border-left:4px solid #7ddfc1;border-radius:9px;padding:14px}.reason{margin:7px 0;color:#b7c7d1}.notice{padding:12px 14px;border-radius:10px;background:#302814;color:#ffd66b;border:1px solid #574719;margin:14px 0}.grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:14px;margin-top:14px}.card{background:#0d1b27;border:1px solid #1c3241;border-radius:14px;padding:18px;min-width:0}.span12{grid-column:span 12}.span8{grid-column:span 8}.span7{grid-column:span 7}.span6{grid-column:span 6}.span5{grid-column:span 5}.span4{grid-column:span 4}.span3{grid-column:span 3}h2{font-size:16px;color:#91ddf2;margin:0 0 14px}.kpi{font-size:25px;font-weight:800;margin:5px 0}.good{color:#52d5aa}.bad{color:#ff7c91}.warn{color:#ffd166}.dim{color:#8295a5}.status{display:inline-block;border-radius:99px;padding:4px 8px;font-size:11px;background:#152a37;color:#a8c2d1}.status.stale{background:#362b18;color:#ffd166}.marketline{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.metric{background:#081722;border-radius:9px;padding:11px}.metric b{display:block;font-size:18px;margin-top:4px}.candidate{padding:14px 0;border-bottom:1px solid #1a3040}.candidate:last-child{border:0}.candidate-head{display:flex;justify-content:space-between;gap:12px}.score-note{padding:10px;background:#10222e;border-radius:8px;color:#9fb1bd;font-size:12px}.bar{height:9px;background:#172b38;border-radius:8px;overflow:hidden;margin:12px 0}.bar i{display:block;height:100%;background:#55d4aa}.timeline{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}.node{padding:11px;border-top:3px solid #36586b;background:#081620;border-radius:8px}.node.DONE{border-color:#52d5aa}.node.INVALID_ENTITY,.node.MISSING{border-color:#ff7c91}table{width:100%;border-collapse:collapse;font-size:12px}th,td{text-align:left;padding:9px;border-bottom:1px solid #1a3040}th{color:#8295a5}.issues{display:grid;gap:8px}.issue{padding:10px;border-left:3px solid #ff7c91;background:#18171e}.tech{overflow-wrap:anywhere;font-size:12px}details{margin-top:14px}summary{cursor:pointer;color:#91ddf2;font-weight:750}.empty{padding:18px 0;color:#8295a5}.view-note{font-size:12px;color:#8295a5;margin-left:auto}.hide{display:none}@media(max-width:820px){.wrap{width:100%;max-width:none;padding:14px}.top{display:block}.lock{display:inline-block;margin-top:10px}.candidate-head{flex-direction:column}.tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));width:100%;gap:6px}.tabs a{padding:9px 5px;text-align:center;white-space:nowrap}.hero{display:block;width:100%;padding:18px}.hero>div+div{margin-top:18px}.grid{display:block;width:100%}.card{width:100%;margin-top:14px;overflow-x:auto}.marketline{grid-template-columns:repeat(2,minmax(0,1fr))}.timeline{grid-template-columns:1fr}.hero h1{font-size:24px}.view-note{display:none}}
"""

REASON_LABELS={"not_confirmed":"尾盘条件未通过，今日不买入","score_policy":"评分未达到当日确认门槛",
 "research_locked":"研究门禁未解除","market_risk":"市场风险较高","data_invalid":"行情数据无效"}

def render(model,view="beginner"):
    s=model.to_dict(); a=s["account"]; m=s["market"]; sent=s["sentiment"]; flow=s["fund_flow"]
    summary=s["summary"]; fresh=s["freshness"]; ev=s["evidence"]; ops=s["operations"]
    valid_market=fresh["market_current"] and m["data_valid"]
    nav="".join(f"<a class='{'active' if view==key else ''}' href='/?view={key}'>{label}</a>" for key,label in (("beginner","新手首页"),("research","研究分析"),("ops","系统运维")))
    reasons="".join(f"<div class='reason'>• {e(REASON_LABELS.get(x,x))}</div>" for x in summary["reasons"]) or "<div class='reason'>• 当前没有额外阻断原因</div>"
    stale="" if fresh["journal_current"] else f"<div class='notice'>当前候选属于历史数据（交易日 {e(fresh['journal_trade_date'] or '未知')}），已禁止作为今天的判断依据。</div>"
    market_status="有效" if valid_market else "不可用/过期"
    sentiment_width=(sent["advance_ratio"] or 0)*100
    candidates=""
    if fresh["journal_current"]:
        for x in s["candidates"]:
            reason="；".join(REASON_LABELS.get(v,v) for v in x["reason_codes"])
            candidates+=f"<article class='candidate'><div class='candidate-head'><div><b>{e(x['name'])} {e(x['code'])}</b><div class='muted'>早盘排名 #{e(x['morning_rank'])} · {e(x['strategy'])}</div></div><span class='status'>{'通过模拟观察门槛' if x['eligible'] else '未确认买入'}</span></div><p>系统相对评分：早盘 {e(x['base_score'])} → 尾盘 {e(x['final_score'] if x['final_score'] is not None else '未入选')}</p><p class='muted'>原因：{e(reason)}</p></article>"
    if not candidates: candidates="<div class='empty'>当前没有可用于今天判断的候选。</div>"
    flows="".join(f"<tr><td>{e(x['name'])}</td><td class='{'good' if x['net_inflow']>=0 else 'bad'}'>{x['net_inflow']:+.2f}亿</td><td>{e(x['change_pct'])}%</td></tr>" for x in flow["sectors"])
    flow_body=(f"<div class='notice'>资金流数据已过期（{e(flow['as_of'])}），不参与今天的市场判断。</div>" if flow["status"]!="current" else "")+(f"<table><tr><th>板块</th><th>净流入</th><th>涨跌幅</th></tr>{flows}</table>" if flows else "<div class='empty'>暂无可用资金流。</div>")
    timeline="".join(f"<div class='node {e(x['status'])}'><b>{e(x['label'])}</b><div class='muted'>{e(x['status'])}</div></div>" for x in s["timeline"])
    task_rows="".join(f"<tr><td>{e(x.get('task_name',''))}</td><td>{e(x.get('status',''))}</td><td>{e(x.get('attempt','—'))}</td><td>{e(x.get('recorded_at',''))}</td></tr>" for x in ops["tasks"])
    issues="".join(f"<div class='issue'><b>{e(x['severity'])} · {e(x['reason_code'])}</b><div>{e(x['message'])}</div></div>" for x in s["issues"]) or "<div class='good'>没有活动告警</div>"
    beginner=f"""<section class='hero'><div><div class='eyebrow'>当前阶段 · {e(summary['phase'])}</div><h1>{e(summary['title'])}</h1><div class='action'><b>现在怎么做</b><div>{e(summary['action'])}</div></div></div><div><div class='eyebrow'>为什么</div>{reasons}</div></section>{stale}
    <div class='grid'><section class='card span3'><div class='muted'>行情可信度</div><div class='kpi {'good' if valid_market else 'bad'}'>{market_status}</div><div class='muted'>覆盖率 {m['coverage']*100:.1f}%</div></section><section class='card span3'><div class='muted'>当日有效候选</div><div class='kpi'>{summary['current_candidate_count']}</div><div class='muted'>仅统计当日实体</div></section><section class='card span3'><div class='muted'>闭合交易样本</div><div class='kpi'>{a['closed_trades']}</div><div class='muted'>不足时不计算胜率</div></section><section class='card span3'><div class='muted'>模拟胜率</div><div class='kpi'>{pct(a['win_rate'])}</div><div class='muted'>不是未来盈利保证</div></section>
    <section class='card span7'><h2>候选分析</h2><div class='score-note'>评分是同一时点候选的相对排序，不是上涨概率，也不是预期收益率。</div>{candidates}</section>
    <section class='card span5'><h2>市场环境</h2><span class='status {'stale' if not valid_market else ''}'>{market_status}</span><div class='marketline'><div class='metric'>上涨<b>{m['rise']}</b></div><div class='metric'>下跌<b>{m['fall']}</b></div><div class='metric'>成交额<b>{m['turnover_yi']:,.0f}亿</b></div><div class='metric'>涨/跌停<b>{m['limit_up']}/{m['limit_down']}</b></div></div><p>市场情绪：<b>{e(sent['breadth_label'])}</b></p><div class='bar'><i style='width:{sentiment_width:.1f}%'></i></div><p class='muted'>有效样本 {sent['sample_size']}；数据无效时禁止判断强弱。截止 {e(m['as_of'] or '无当日数据')}</p></section>
    <section class='card span6'><h2>板块资金流</h2>{flow_body}</section><section class='card span6'><h2>策略验证进度</h2><p>严格14:50/09:30样本：<b>{ev['strict']['pairs']}</b> 对</p><p>模拟闭合交易：<b>{a['closed_trades']}</b> 笔</p><p>模型状态：<b class='warn'>{e(ev['model_status'])}</b></p><div class='notice'>现阶段首先验证系统运行正确性；样本不足，不能评价策略盈利能力。</div></section></div>"""
    research=f"""<div class='grid'><section class='card span12'><h2>09:25 → 14:49 → 14:50 → 次日09:30</h2><div class='timeline'>{timeline}</div></section><section class='card span12'><h2>候选评分研究</h2><div class='score-note'>研究评分不是概率。候选必须来自同日母池，尾盘只在母池内确认。</div>{candidates}</section><section class='card span6'><h2>模拟账户与回撤</h2><p>账户权益 <b>¥{a['equity']:,.2f}</b></p><p>净盈亏 <b>¥{a['net_pnl']:+,.2f}</b> · 最大回撤 {a['max_drawdown']*100:.2f}%</p><p>平均单笔 {('样本不足' if a['average_pnl'] is None else f"¥{a['average_pnl']:+,.2f}")}</p></section><section class='card span6'><h2>证据分层</h2><p>严格样本 {ev['strict']['pairs']} 对 · Paper {ev['paper']['round_trips']} 笔 · 15:00代理 {ev['proxy']['trades']} 笔</p><p class='muted'>三类证据严格隔离，代理回测不得替代真实严格样本。</p></section>{render_windows(s)}</div>"""
    owner=ops["ownership"]; cut=ops["cutover"]
    ops_view=f"""<div class='grid'><section class='card span7'><h2>数据与运行告警</h2><div class='issues'>{issues}</div></section><section class='card span5'><h2>运行状态</h2><p>心跳：<b>{e(ops['heartbeat_status'])}</b></p><p class='muted'>{e(ops['heartbeat_at'])}</p><p>所有者：决策 {e(owner.get('decision'))} · 账户 {e(owner.get('account_execution'))} · 调度 {e(owner.get('scheduler_notifications'))} · 看板 {e(owner.get('dashboard'))}</p><p>切换：{'APPLIED' if cut.get('applied') else 'PENDING'}</p></section><section class='card span12'><h2>P4任务与SLA</h2><table><tr><th>任务</th><th>状态</th><th>尝试</th><th>时间</th></tr>{task_rows}</table></section><section class='card span12'><details><summary>来源、实体ID与哈希</summary><div class='tech'>{''.join(f"<p>{e(x.get('name'))} · {e(x.get('status'))} · {e(x.get('sha256') or x.get('error'))}</p>" for x in s['sources'])}</div></details></section></div>"""
    content={"research":research,"ops":ops_view}.get(view,beginner)
    return f"<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width'><title>V4 股票研究助手</title><style>{CSS}</style></head><body><main class='wrap' data-testid='p5-dashboard'><header class='top'><div><div class='brand'>A股隔夜研究助手 <em>V4</em></div><div class='sub'>本地只读模拟系统 · 不连接券商 · 不构成投资建议</div></div><span class='lock'>{e(s['production_status'])}</span></header><nav class='tabs'>{nav}<span class='view-note'>数据来自冻结实体投影</span></nav>{content}</main></body></html>"

def render_windows(s):
    rows="".join(f"<tr><td>{e(x['name'])}</td><td>{e(x['status'])}</td><td>{e('；'.join(x['reasons']) or '—')}</td></tr>" for x in s["evidence"]["live_windows"])
    return f"<section class='card span12'><h2>四个真实窗口验收</h2><table><tr><th>窗口</th><th>状态</th><th>原因</th></tr>{rows}</table></section>"
